const { getLayout } = options;
const switcher = document.getElementById('viewers');
const currentActivePaneId = switcher.activePaneId;
const newActivePaneId = currentActivePaneId === 'dashboard-editor' ? 'formTab' : 'dashboard-editor';
switcher.activePaneId = newActivePaneId;
getLayout().setState((state) => {
	state.activePaneId = newActivePaneId;
});
